WITH parsed AS (SELECT id, host, log_ts, level, status_code, context, context['region'] AS region, CAST((status_code & 2) != 0 AS INT) AS flag_bit2, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs WHERE HOUR(log_ts) BETWEEN 11 AND 15) SELECT *, SUM(flag_bit2) OVER w_ordered AS running_flag_bit2, LAST_VALUE(tier) IGNORE NULLS OVER w_ordered AS last_known_tier, SUM(flag_bit2) OVER (ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_flag_bit2, SUM(flag_bit2) OVER (PARTITION BY level ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_flag_bit2_2 FROM parsed WINDOW w_ordered AS (PARTITION BY level, tier ORDER BY status_code, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
